    def read_int():
        return int(sys.stdin.readline())

    def read_list_int():
        return list(map(int, sys.stdin.readline().split()))

    t = read_int()
    results = []

    for _ in range(t):
        n = read_int()
        a = read_list_int()

        skip_points = 0
        i = 0

        while i < n:
            if i % 2 == 0:  # Friend's turn
                if a[i] == 1:
                    skip_points += 1
                if i + 1 < n and a[i + 1] == 1:
                    skip_points += 1
                i += 2
            else:  # Your turn
                i += 2

        results.append(skip_points)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
